// server/src/services/board.service.ts
import { prisma } from '../lib/prisma';
import { AppError } from '../middleware/error-handler';

export class BoardService {
  async getAll(userId: string) {
    return prisma.board.findMany({
      where: { userId },
      include: {
        lists: {
          orderBy: { position: 'asc' },
          include: {
            cards: {
              orderBy: { position: 'asc' },
            },
          },
        },
        _count: { select: { lists: true } },
      },
      orderBy: { updatedAt: 'desc' },
    });
  }

  async getById(id: string, userId: string) {
    const board = await prisma.board.findFirst({
      where: { id, userId },
      include: {
        lists: {
          orderBy: { position: 'asc' },
          include: {
            cards: {
              orderBy: { position: 'asc' },
              include: { assignee: { select: { id: true, name: true, avatar: true } } },
            },
          },
        },
      },
    });

    if (!board) {
      throw new AppError('Board bulunamadı', 404);
    }

    return board;
  }

  async create(userId: string, data: { title: string; color?: string }) {
    return prisma.board.create({
      data: {
        title: data.title,
        color: data.color || '#3b82f6',
        userId,
        lists: {
          create: [
            { title: 'Yapılacak', position: 0 },
            { title: 'Devam Eden', position: 1 },
            { title: 'Tamamlanan', position: 2 },
          ],
        },
      },
      include: { lists: true },
    });
  }

  async update(id: string, userId: string, data: { title?: string; color?: string }) {
    const board = await prisma.board.findFirst({ where: { id, userId } });
    if (!board) throw new AppError('Board bulunamadı', 404);

    return prisma.board.update({
      where: { id },
      data,
    });
  }

  async delete(id: string, userId: string) {
    const board = await prisma.board.findFirst({ where: { id, userId } });
    if (!board) throw new AppError('Board bulunamadı', 404);

    return prisma.board.delete({ where: { id } });
  }
}

