// server/src/services/card.service.ts
import { prisma } from '../lib/prisma';
import { AppError } from '../middleware/error-handler';

export class CardService {
  async create(listId: string, data: { title: string; description?: string }) {
    const list = await prisma.list.findUnique({ where: { id: listId } });
    if (!list) throw new AppError('List bulunamadı', 404);

    const maxPosition = await prisma.card.aggregate({
      where: { listId },
      _max: { position: true },
    });

    return prisma.card.create({
      data: {
        ...data,
        listId,
        position: (maxPosition._max.position ?? -1) + 1,
      },
    });
  }

  async move(cardId: string, targetListId: string, newPosition: number) {
    const card = await prisma.card.findUnique({ where: { id: cardId } });
    if (!card) throw new AppError('Card bulunamadı', 404);

    return prisma.$transaction(async (tx) => {
      // Hedef listteki kartların pozisyonlarını güncelle
      await tx.card.updateMany({
        where: {
          listId: targetListId,
          position: { gte: newPosition },
        },
        data: { position: { increment: 1 } },
      });

      // Kaynak listteki boşluğu kapat
      if (card.listId !== targetListId) {
        await tx.card.updateMany({
          where: {
            listId: card.listId,
            position: { gt: card.position },
          },
          data: { position: { decrement: 1 } },
        });
      }

      // Kartı taşı
      return tx.card.update({
        where: { id: cardId },
        data: { listId: targetListId, position: newPosition },
      });
    });
  }

  async update(cardId: string, data: {
    title?: string;
    description?: string;
    dueDate?: Date | null;
    labels?: string[];
  }) {
    return prisma.card.update({
      where: { id: cardId },
      data,
    });
  }

  async delete(cardId: string) {
    const card = await prisma.card.findUnique({ where: { id: cardId } });
    if (!card) throw new AppError('Card bulunamadı', 404);

    return prisma.$transaction(async (tx) => {
      await tx.card.delete({ where: { id: cardId } });
      // Silinen kartın altındaki kartların pozisyonlarını güncelle
      await tx.card.updateMany({
        where: {
          listId: card.listId,
          position: { gt: card.position },
        },
        data: { position: { decrement: 1 } },
      });
    });
  }
}

