import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '../lib/api';

export function AddCard({ listId, boardId }: { listId: string; boardId: string }) {
  const [isAdding, setIsAdding] = useState(false);
  const [title, setTitle] = useState('');
  const queryClient = useQueryClient();

  const createCard = useMutation({
    mutationFn: async (data: { title: string }) => {
      const { data: result } = await api.post(`/lists/${listId}/cards`, data);
      return result.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['board', boardId] });
      setTitle('');
      setIsAdding(false);
    },
  });

  if (!isAdding) {
    return (
      <button
        onClick={() => setIsAdding(true)}
        className="m-2 rounded-lg p-2 text-left text-sm text-gray-500 transition-colors hover:bg-gray-200 dark:hover:bg-gray-700"
      >
        + Kart ekle
      </button>
    );
  }

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (title.trim()) createCard.mutate({ title: title.trim() });
      }}
      className="p-2"
    >
      <textarea
        autoFocus
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            if (title.trim()) createCard.mutate({ title: title.trim() });
          }
          if (e.key === 'Escape') setIsAdding(false);
        }}
        placeholder="Kart başlığı girin..."
        className="w-full resize-none rounded-lg border p-2 text-sm focus:border-blue-500 focus:outline-none dark:border-gray-600 dark:bg-gray-700"
        rows={2}
      />
      <div className="mt-2 flex gap-2">
        <button
          type="submit"
          disabled={!title.trim() || createCard.isPending}
          className="rounded-lg bg-blue-600 px-3 py-1 text-sm text-white hover:bg-blue-700 disabled:opacity-50"
        >
          Ekle
        </button>
        <button
          type="button"
          onClick={() => setIsAdding(false)}
          className="rounded-lg px-3 py-1 text-sm text-gray-500 hover:bg-gray-200"
        >
          İptal
        </button>
      </div>
    </form>
  );
}

