// props değiştiğinde (API'den yeni veri geldiğinde) senkronize et
React.useEffect(() => { setLocalLists(lists) }, [lists])

function handleDragEnd(event: any) {
  const { active, over } = event
  if (!over || active.id === over.id) return

  setLocalLists(prev => {
    const newLists = prev.map(l => ({ ...l, cards: [...l.cards] }))
    let sourceList = newLists.find(l => l.cards.some((c: any) => c.id === active.id))
    let targetList = newLists.find(l => l.id === over.id || l.cards.some((c: any) => c.id === over.id))

    if (!sourceList || !targetList) return prev

    const cardIndex = sourceList.cards.findIndex((c: any) => c.id === active.id)
    const [card] = sourceList.cards.splice(cardIndex, 1)
    targetList.cards.push(card)
    return newLists
  })
}

