import request from 'supertest';
import app from '../src/app';

describe('Boards API', () => {
  let authToken: string;

  beforeEach(async () => {
    const res = await request(app)
      .post('/api/auth/register')
      .send({ email: 'test@test.com', name: 'User', password: 'Password123' });
    authToken = res.body.data.accessToken;
  });

  describe('POST /api/boards', () => {
    it('should create a board with default lists', async () => {
      const res = await request(app)
        .post('/api/boards')
        .set('Authorization', `Bearer ${authToken}`)
        .send({ title: 'Test Board' });

      expect(res.status).toBe(201);
      expect(res.body.data.title).toBe('Test Board');
      expect(res.body.data.lists).toHaveLength(3);
    });

    it('should reject without auth', async () => {
      const res = await request(app)
        .post('/api/boards')
        .send({ title: 'Test Board' });

      expect(res.status).toBe(401);
    });
  });

  describe('GET /api/boards', () => {
    it('should return only user boards', async () => {
      await request(app)
        .post('/api/boards')
        .set('Authorization', `Bearer ${authToken}`)
        .send({ title: 'Board 1' });

      // Başka kullanıcı
      const otherUser = await request(app)
        .post('/api/auth/register')
        .send({ email: 'other@test.com', name: 'Other', password: 'Password123' });

      await request(app)
        .post('/api/boards')
        .set('Authorization', `Bearer ${otherUser.body.data.accessToken}`)
        .send({ title: 'Other Board' });

      const res = await request(app)
        .get('/api/boards')
        .set('Authorization', `Bearer ${authToken}`);

      expect(res.status).toBe(200);
      expect(res.body.data).toHaveLength(1);
      expect(res.body.data[0].title).toBe('Board 1');
    });
  });
});

