import request from 'supertest'
import { app, cleanDatabase } from './setup'

let token: string

describe('Board API', () => {
  beforeEach(async () => {
    await cleanDatabase()

  const res = await request(app)
    .post('/api/auth/register')
    .send({ email: 'test@test.com', password: 'Test1234!', name: 'Test' })
  token = res.body.data.accessToken
})

})

it('board listesini getirebilmeli', async () => {
  await request(app).post('/api/boards')
    .set('Authorization', `Bearer ${token}`)
    .send({ title: 'Board 1' })
  const res = await request(app).get('/api/boards')
    .set('Authorization', `Bearer ${token}`)

  expect(res.status).toBe(200)
  expect(res.body.data).toHaveLength(1)
})

it('token olmadan board listesine erişememeli', async () => {
  const res = await request(app).get('/api/boards')
  expect(res.status).toBe(401)
})

it('başka kullanıcının board\'unu görememeli', async () => {
  await request(app).post('/api/boards')
    .set('Authorization', `Bearer ${token}`)

    .send({ title: 'Private Board' })
  const res2 = await request(app).post('/api/auth/register')
    .send({ email: 'other@test.com', password: 'Test1234!', name: 'Other' })
  const otherToken = res2.body.data.accessToken
  const res = await request(app).get('/api/boards')
    .set('Authorization', `Bearer ${otherToken}`)
  expect(res.body.data).toHaveLength(0)
})

