// client/src/components/__tests__/kanban-card.test.tsx
import { render, screen } from '@testing-library/react';
import { KanbanCard } from '../kanban-card';

describe('KanbanCard', () => {
  const mockCard = {
    id: '1',
    title: 'Test Kartı',
    description: 'Açıklama',
    labels: ['frontend', 'bug'],
    dueDate: '2024-12-31',
  };

  it('should render card title', () => {
    render(<KanbanCard card={mockCard} />);
    expect(screen.getByText('Test Kartı')).toBeInTheDocument();
  });

  it('should render labels', () => {
    render(<KanbanCard card={mockCard} />);
    expect(screen.getByText('frontend')).toBeInTheDocument();
    expect(screen.getByText('bug')).toBeInTheDocument();
  });

  it('should render due date', () => {
    render(<KanbanCard card={mockCard} />);
    expect(screen.getByText('31.12.2024')).toBeInTheDocument();
  });

  it('should not render labels section when empty', () => {
    render(<KanbanCard card={{ ...mockCard, labels: [] }} />);
    expect(screen.queryByText('frontend')).not.toBeInTheDocument();
  });
});

